const firebaseApp = initializeApp({apiKey:'AIzaSyBdZNPBnJXeMAEjt-Djr_YcbGhB9HvFfco',authDomain:'khushi-homes-6db7b.firebaseapp.com',projectId:'khushi-homes-6db7b',storageBucket:'khushi-homes-6db7b.firebasestorage.app',messagingSenderId:'351498186013',appId:'1:351498186013:web:ad7e928e77220b3d7385f4',measurementId:'G-RRCMG225YY'});
