type PaymentRecord = {id:string;planName:string;amount:number;method:string;status:'Success'|'Failed';paymentId?:string;date:string};

const iconFor = (type:DeviceType) => type==='Light'?Lightbulb:type==='Fan'?Fan:type==='AC'?Wind:type==='TV'?Tv:type==='Smart Plug'?PlugZap:type==='Camera'?Camera:SlidersHorizontal;
